put('compare_shadow474.py',copy('compare_shadow470.py').replace('B_experts_on_minus_off','B_decoder_on_minus_off').replace('B_routing_on_minus_off','B_conditional_on_minus_off').replace('ROUTING_OFF','CONDITIONAL_OFF'))
